import { registered } from "./registry.generated.js";
import type { Connector } from "./types.js";

/**
 * Connector registry: the connectors the CLI runs.
 *
 * It is generated by `scripts/gen-connectors.mjs` (run automatically before
 * build, typecheck, lint and test). To add a connector, create
 * `src/connectors/<id>.ts` with `export const connector: Connector` whose `id`
 * equals the file name. No shared file needs editing.
 *
 * `example.ts` is a template for contributors, only used in tests, and is never
 * registered.
 */
export const connectors: readonly Connector[] = Object.freeze([...registered]);

export function getConnector(id: string): Connector | undefined {
  return connectors.find((c) => c.id === id);
}

export type { Connector, Finding, CheckContext, Level, Confidence, Capability } from "./types.js";
